#!/usr/bin/env python3
"""Generate the optional north HTTP OpenAPI document from EOS proto descriptors."""

from __future__ import annotations

import argparse
import importlib
import json
import os
import re
import subprocess
import sys
import tempfile
from pathlib import Path

# Accept Python modules generated by Ubuntu 22.04's protoc 3.12.
os.environ.setdefault("PROTOCOL_BUFFERS_PYTHON_IMPLEMENTATION", "python")

try:
  from google.protobuf import descriptor_pb2
except ImportError as error:
  raise SystemExit("generate_north_http_openapi: Python package 'protobuf' is required") from error


ROOT = Path(__file__).resolve().parents[1]
SERVICES = ("eos/gateway.proto", "eos/skills.proto", "eos/workflow.proto")
SCALAR_TYPES = {
    1: {"type": "number"}, 2: {"type": "number"}, 3: {"type": "string", "pattern": "^-?[0-9]+$"},
    4: {"type": "string", "pattern": "^[0-9]+$"}, 5: {"type": "integer"},
    6: {"type": "string", "pattern": "^[0-9]+$"}, 7: {"type": "integer"},
    8: {"type": "boolean"}, 9: {"type": "string"},
    12: {"type": "string", "contentEncoding": "base64"}, 13: {"type": "integer"},
    15: {"type": "integer"}, 16: {"type": "string", "pattern": "^-?[0-9]+$"},
    17: {"type": "integer"}, 18: {"type": "string", "pattern": "^[0-9]+$"},
}
SPECIAL = {
    ".google.protobuf.Empty": {"type": "object", "additionalProperties": False},
    ".google.protobuf.Struct": {"type": "object", "additionalProperties": True},
    ".google.protobuf.Value": {},
    ".google.protobuf.ListValue": {"type": "array", "items": {}},
    ".google.protobuf.Timestamp": {"type": "string", "format": "date-time"},
    ".google.protobuf.Duration": {"type": "string", "format": "duration"},
}


def descriptor_set(proto_root: Path):
  """Compile service descriptors and load their declared HTTP options."""
  with tempfile.TemporaryDirectory(prefix="eos-openapi-") as temporary:
    directory = Path(temporary)
    output = directory / "services.pb"
    commands = (
        ["protoc", "--experimental_allow_proto3_optional", f"-I{proto_root}",
         f"--descriptor_set_out={output}",
         "--include_imports", *SERVICES],
        ["protoc", "--experimental_allow_proto3_optional", f"-I{proto_root}",
         f"--python_out={directory}",
         "google/api/http.proto", "google/api/annotations.proto", "eos/external/http/http.proto"],
    )
    for command in commands:
      try:
        subprocess.run(command, cwd=proto_root, check=True, capture_output=True, text=True)
      except FileNotFoundError as error:
        raise ValueError("protoc is required") from error
      except subprocess.CalledProcessError as error:
        raise ValueError(error.stderr.strip() or "protoc failed") from error
    sys.path.insert(0, str(directory))
    try:
      annotation = importlib.import_module("google.api.annotations_pb2")
      routes = importlib.import_module("eos.external.http.http_pb2")
      return (descriptor_pb2.FileDescriptorSet.FromString(output.read_bytes()),
              annotation.http, routes.http_route)
    finally:
      sys.path.pop(0)


def schema_name(full_name: str) -> str:
  return full_name.lstrip(".").replace(".", "_")


def ref(full_name: str) -> dict:
  if full_name in SPECIAL:
    return dict(SPECIAL[full_name])
  return {"$ref": "#/components/schemas/" + schema_name(full_name)}


def collect_types(descriptors):
  messages = {}
  enums = {}

  def visit_message(message, prefix):
    name = prefix + "." + message.name
    messages[name] = message
    for nested in message.nested_type:
      visit_message(nested, name)
    for enum in message.enum_type:
      enums[name + "." + enum.name] = enum

  for file in descriptors.file:
    prefix = "." + file.package
    for message in file.message_type:
      visit_message(message, prefix)
    for enum in file.enum_type:
      enums[prefix + "." + enum.name] = enum
  return messages, enums


def render_types(messages, enums):
  result = {}
  for full_name, enum in enums.items():
    result[schema_name(full_name)] = {"type": "string", "enum": [value.name for value in enum.value]}
  for full_name, message in messages.items():
    if full_name in SPECIAL or message.options.map_entry:
      continue
    properties = {}
    for field in message.field:
      name = field.json_name or field.name
      if field.type in (descriptor_pb2.FieldDescriptorProto.TYPE_MESSAGE,
                        descriptor_pb2.FieldDescriptorProto.TYPE_ENUM):
        value = ref(field.type_name)
      else:
        value = dict(SCALAR_TYPES.get(field.type, {}))
      if field.label == descriptor_pb2.FieldDescriptorProto.LABEL_REPEATED:
        value = {"type": "array", "items": value}
      properties[name] = value
    result[schema_name(full_name)] = {"type": "object", "properties": properties}
  return result


def add_operation(paths, method, path, operation):
  key = method.lower()
  slot = paths.setdefault(path, {})
  if key in slot:
    raise ValueError(f"duplicate HTTP route: {method} {path}")
  slot[key] = operation


def render(proto_root: Path, runtime_root: Path) -> dict:
  descriptors, http_option, route_option = descriptor_set(proto_root)
  messages, enums = collect_types(descriptors)
  components = render_types(messages, enums)
  paths = {}
  for file in descriptors.file:
    if file.name not in SERVICES:
      continue
    for service in file.service:
      for rpc in service.method:
        if not rpc.options.HasExtension(http_option):
          continue
        binding = rpc.options.Extensions[http_option]
        method = binding.WhichOneof("pattern")
        if method not in {"get", "post", "put", "patch", "delete"}:
          continue
        path = getattr(binding, method)
        response = ref(rpc.output_type)
        streamed = rpc.server_streaming
        operation = {
            "operationId": service.name + "_" + rpc.name,
            "tags": [service.name],
            "responses": {"200": {"description": "Success", "content": {
                "text/event-stream" if streamed else "application/json": {"schema": response}}}},
            "x-eos-grpc-method": f"/{file.package}.{service.name}/{rpc.name}",
        }
        if streamed:
          operation["x-eos-transport"] = "sse"
        path_fields = set(re.findall(r"\{([^{}]+)\}", path))
        parameters = [
            {"name": name, "in": "path", "required": True, "schema": {"type": "string"}}
            for name in sorted(path_fields)
        ]
        request = messages.get(rpc.input_type)
        if request is not None and method == "get":
          for field in request.field:
            if field.name in path_fields or field.json_name in path_fields:
              continue
            parameters.append({"name": field.json_name or field.name, "in": "query",
                               "schema": {"type": "string"}})
        if parameters:
          operation["parameters"] = parameters
        if binding.body:
          operation["requestBody"] = {"content": {"application/json": {
              "schema": ref(rpc.input_type)}}}
        add_operation(paths, method, path, operation)
    for route in file.options.Extensions[route_option]:
      transport = route.transport or "json"
      content_type = {"json": "application/json", "sse": "text/event-stream",
                      "websocket": "application/json"}.get(transport)
      if content_type is None:
        raise ValueError(f"unknown HTTP transport: {transport}")
      response = ref("." + route.response_type) if route.response_type else {}
      operation = {
          "operationId": "Http_" + re.sub(r"[^A-Za-z0-9]+", "_", route.path).strip("_"),
          "summary": route.summary,
          "tags": ["NorthHttp"],
          "responses": {"200": {"description": "Success", "content": {content_type: {
              "schema": response}}}},
          "x-eos-transport": transport,
      }
      add_operation(paths, route.method, route.path, operation)

  for file in sorted(runtime_root.glob("*/*.json")):
    schema = json.loads(file.read_text(encoding="utf-8"))
    components["EOS_" + file.parent.name + "_" + file.stem.replace(".", "_")] = schema
  # Protoc 3.12 lacks this FieldOptions member; it is not part of the HTTP API.
  components.get("google_protobuf_FieldOptions", {}).get("properties", {}).pop(
      "unverifiedLazy", None)
  return {
      "openapi": "3.1.0",
      "info": {"title": "Aether EOS north HTTP API", "version": "1.0.0"},
      "paths": paths,
      "components": {"schemas": components},
  }


def main() -> int:
  parser = argparse.ArgumentParser(description=__doc__)
  parser.add_argument("--proto-root", type=Path, default=ROOT / "share/contracts")
  parser.add_argument("--runtime-root", type=Path, default=ROOT / "share/ext/eos")
  parser.add_argument("--output", type=Path, default=ROOT / "share/ext/north_http/openapi.json")
  parser.add_argument("--check", action="store_true")
  args = parser.parse_args()
  try:
    document = render(args.proto_root.resolve(), args.runtime_root.resolve())
    encoded = (json.dumps(document, indent=2, sort_keys=True, ensure_ascii=False) + "\n").encode()
    output = args.output.resolve()
    if args.check:
      if not output.is_file() or output.read_bytes() != encoded:
        raise ValueError(f"stale OpenAPI document: {output}")
    else:
      output.parent.mkdir(parents=True, exist_ok=True)
      output.write_bytes(encoded)
  except (ValueError, OSError, json.JSONDecodeError) as error:
    print(f"generate_north_http_openapi: {error}", file=sys.stderr)
    return 1
  return 0


if __name__ == "__main__":
  raise SystemExit(main())
